from __future__ import annotations

import os
from dataclasses import dataclass
from functools import lru_cache

from backend.shared.authz.claims import normalize_header_names, parse_group_values


_TRUE_VALUES = {"1", "true", "yes", "on"}
_FALSE_VALUES = {"0", "false", "no", "off"}


def _read_env(*names: str) -> str | None:
    for name in names:
        value = os.getenv(name)
        if value is not None:
            return value
    return None


def _read_bool(default: bool, *names: str) -> bool:
    raw = _read_env(*names)
    if raw is None:
        return default

    normalized = raw.strip().lower()
    if normalized in _TRUE_VALUES:
        return True
    if normalized in _FALSE_VALUES:
        return False
    return default


def _read_headers(default: tuple[str, ...], *names: str) -> tuple[str, ...]:
    raw = _read_env(*names)
    if raw is None:
        return default

    parsed = parse_group_values(raw)
    if not parsed:
        return default
    return normalize_header_names(parsed)


def _read_groups(default: tuple[str, ...], *names: str) -> tuple[str, ...]:
    raw = _read_env(*names)
    if raw is None:
        return default

    parsed = parse_group_values(raw)
    return parsed or default


@dataclass(frozen=True)
class AuthzSettings:
    enabled: bool = True
    allow_anonymous: bool = False
    state_principal_key: str = "session_principal"
    subject_headers: tuple[str, ...] = (
        "x-user-id",
        "x-auth-request-user",
        "x-forwarded-user",
    )
    email_headers: tuple[str, ...] = (
        "x-user-email",
        "x-auth-request-email",
        "x-forwarded-email",
    )
    display_name_headers: tuple[str, ...] = (
        "x-user-name",
        "x-auth-request-name",
        "x-forwarded-name",
    )
    group_headers: tuple[str, ...] = (
        "x-user-groups",
        "x-auth-request-groups",
        "x-groups",
        "x-roles",
    )
    admin_groups: tuple[str, ...] = (
        "admin",
        "docufu-admin",
    )
    reviewer_groups: tuple[str, ...] = (
        "reviewer",
        "validator",
        "docufu-reviewer",
    )

    @classmethod
    def from_env(cls) -> "AuthzSettings":
        return cls(
            enabled=_read_bool(True, "AUTHZ_ENABLED", "DOCUFU_AUTHZ_ENABLED"),
            allow_anonymous=_read_bool(
                False,
                "AUTHZ_ALLOW_ANONYMOUS",
                "DOCUFU_AUTHZ_ALLOW_ANONYMOUS",
            ),
            state_principal_key=(
                _read_env("AUTHZ_STATE_PRINCIPAL_KEY", "DOCUFU_AUTHZ_STATE_PRINCIPAL_KEY")
                or "session_principal"
            ).strip(),
            subject_headers=_read_headers(
