from __future__ import annotations

import logging

from backend.shared.authz.models import AuthorizationDecision, SessionPrincipal


LOGGER_NAME = "backend.shared.authz"


def get_authz_logger() -> logging.Logger:
    return logging.getLogger(LOGGER_NAME)


def _redact_email(email: str | None) -> str | None:
    if not email or "@" not in email:
        return email

    local_part, domain = email.split("@", 1)
    if len(local_part) <= 2:
        visible = local_part[:1]
    else:
        visible = f"{local_part[:2]}***"
    return f"{visible}@{domain}"


def principal_log_fields(principal: SessionPrincipal) -> dict[str, object]:
    return {
        "authenticated": principal.authenticated,
        "subject": principal.subject,
        "email": _redact_email(principal.email),
        "groups": list(principal.groups),
        "roles": list(principal.roles),
        "source": principal.source,
    }


def decision_log_fields(decision: AuthorizationDecision) -> dict[str, object]:
    return {
        "allowed": decision.allowed,
        "required_groups": list(decision.required_groups),
        "matched_groups": list(decision.matched_groups),
        "reason": decision.reason,
    }


def log_access_denied(
    route_name: str,
    *,
    principal: SessionPrincipal,
    decision: AuthorizationDecision,
) -> None:
    get_authz_logger().warning(
        "Session RBAC access denied",
        extra={
            "route": route_name,
            "principal": principal_log_fields(principal),
            "decision": decision_log_fields(decision),
        },
    )


__all__ = [
    "LOGGER_NAME",
    "decision_log_fields",
    "get_authz_logger",
