from __future__ import annotations

import json
import re
from collections.abc import Mapping
from typing import Any, Optional

from backend.shared.authz.models import SessionPrincipal


_SPLIT_PATTERN = re.compile(r"[;,]")


def _unique_preserve_order(values: list[str]) -> tuple[str, ...]:
    seen: set[str] = set()
    ordered: list[str] = []
    for value in values:
        if value not in seen:
            seen.add(value)
            ordered.append(value)
    return tuple(ordered)


def _clean_text(value: Any) -> Optional[str]:
    if value is None:
        return None
    text = str(value).strip()
    return text or None


def normalize_header_names(values: tuple[str, ...] | list[str]) -> tuple[str, ...]:
    return _unique_preserve_order(
        [str(value).strip().lower() for value in values if str(value).strip()]
    )


def parse_group_values(value: Any) -> tuple[str, ...]:
    if value is None:
        return ()

    if isinstance(value, (list, tuple, set, frozenset)):
        raw_items = [str(item) for item in value]
    else:
        text = _clean_text(value)
        if not text:
            return ()

        if text.startswith("[") and text.endswith("]"):
            try:
                parsed = json.loads(text)
                if isinstance(parsed, list):
                    raw_items = [str(item) for item in parsed]
                else:
                    raw_items = [text]
            except json.JSONDecodeError:
                raw_items = _SPLIT_PATTERN.split(text)
        else:
            raw_items = _SPLIT_PATTERN.split(text)

    cleaned = [item.strip().lower() for item in raw_items if item and item.strip()]
    return _unique_preserve_order(cleaned)


def _resolve_first_value(
    headers: Mapping[str, Any],
    header_names: tuple[str, ...],
) -> tuple[Optional[str], tuple[str, ...]]:
    matched_keys: list[str] = []
    for header_name in header_names:
        value = _clean_text(headers.get(header_name))
        if value:
            matched_keys.append(header_name.lower())
            return value, tuple(matched_keys)
    return None, tuple(matched_keys)


def _resolve_group_values(
    headers: Mapping[str, Any],
    header_names: tuple[str, ...],
) -> tuple[tuple[str, ...], tuple[str, ...]]:
    groups: list[str] = []
    matched_keys: list[str] = []

    for header_name in header_names:
        value = headers.get(header_name)
        parsed = parse_group_values(value)
        if parsed:
            matched_keys.append(header_name.lower())
            groups.extend(parsed)

    return _unique_preserve_order(groups), tuple(matched_keys)


def principal_from_headers(
    headers: Mapping[str, Any],
    *,
    subject_headers: tuple[str, ...],
    email_headers: tuple[str, ...],
    display_name_headers: tuple[str, ...],
    group_headers: tuple[str, ...],
    source: str = "proxy_headers",
) -> Optional[SessionPrincipal]:
    subject, subject_keys = _resolve_first_value(headers, subject_headers)
    if not subject:
        return None

    email, email_keys = _resolve_first_value(headers, email_headers)
    display_name, display_name_keys = _resolve_first_value(headers, display_name_headers)
    groups, group_keys = _resolve_group_values(headers, group_headers)

    raw_claim_keys = _unique_preserve_order(
        list(subject_keys) + list(email_keys) + list(display_name_keys) + list(group_keys)
    )

    return SessionPrincipal(
        authenticated=True,
        subject=subject,
        email=email,
        display_name=display_name,
        groups=groups,
        roles=(),
        source=source,
        raw_claim_keys=raw_claim_keys,
    )


def principal_from_state(value: Any, *, source: str = "request_state") -> Optional[SessionPrincipal]:
    if value is None:
        return None

    if isinstance(value, SessionPrincipal):
        data = (
            value.model_dump()
            if hasattr(value, "model_dump")
            else value.dict()
        )
        data["source"] = source
        return SessionPrincipal(**data)

    if isinstance(value, Mapping):
        subject = _clean_text(value.get("subject") or value.get("sub") or value.get("user_id"))
        if not subject:
            return None

        groups = parse_group_values(value.get("groups") or value.get("roles"))
        raw_claim_keys = _unique_preserve_order([str(key) for key in value.keys()])

        return SessionPrincipal(
            authenticated=bool(value.get("authenticated", True)),
            subject=subject,
            email=_clean_text(value.get("email")),
            display_name=_clean_text(value.get("display_name") or value.get("name")),
            groups=groups,
            roles=parse_group_values(value.get("resolved_roles") or value.get("app_roles")),
            source=source,
            raw_claim_keys=raw_claim_keys,
        )

    return None


__all__ = [
    "normalize_header_names",
    "parse_group_values",
    "principal_from_headers",
    "principal_from_state",
]
