from __future__ import annotations

from typing import Iterable

from fastapi import Depends, HTTPException, Request, status

from backend.shared.authz.claims import principal_from_headers, principal_from_state
from backend.shared.authz.logging import log_access_denied
from backend.shared.authz.models import AuthorizationDecision, SessionAuthorizationContext, SessionPrincipal
from backend.shared.authz.settings import (
    AuthzSettings,
    clear_authz_settings_cache,
    get_authz_settings,
)


def _normalize_groups(values: Iterable[str]) -> tuple[str, ...]:
    ordered: list[str] = []
    seen: set[str] = set()

    for value in values:
        normalized = str(value).strip().lower()
        if normalized and normalized not in seen:
            seen.add(normalized)
            ordered.append(normalized)

    return tuple(ordered)


def _model_to_dict(principal: SessionPrincipal) -> dict[str, object]:
    if hasattr(principal, "model_dump"):
        return principal.model_dump()
    return principal.dict()


def _with_roles(principal: SessionPrincipal, roles: tuple[str, ...]) -> SessionPrincipal:
    data = _model_to_dict(principal)
    data["roles"] = roles
    return SessionPrincipal(**data)


def _matches_any_group(principal_groups: tuple[str, ...], required_groups: tuple[str, ...]) -> tuple[str, ...]:
    required = set(required_groups)
    return tuple(group for group in principal_groups if group in required)


def derive_roles(principal: SessionPrincipal, settings: AuthzSettings) -> SessionPrincipal:
    if not principal.authenticated:
        return _with_roles(principal, ("anonymous",))

    roles = set(principal.roles)
    roles.add("authenticated")

    if _matches_any_group(principal.groups, settings.admin_groups):
        roles.add("admin")

    if _matches_any_group(principal.groups, settings.reviewer_groups):
        roles.add("reviewer")

    if roles == {"authenticated"}:
        roles.add("user")

    return _with_roles(principal, tuple(sorted(roles)))


def evaluate_group_access(
    principal: SessionPrincipal,
    required_groups: tuple[str, ...],
    *,
    access_label: str,
) -> AuthorizationDecision:
    normalized_required = _normalize_groups(required_groups)

    if not normalized_required:
        return AuthorizationDecision(
            allowed=False,
            required_groups=(),
            matched_groups=(),
            reason=f"No {access_label} groups are configured.",
        )

    if not principal.authenticated:
        return AuthorizationDecision(
            allowed=False,
            required_groups=normalized_required,
            matched_groups=(),
            reason=f"Anonymous session does not satisfy {access_label} access.",
        )

    matched_groups = _matches_any_group(principal.groups, normalized_required)
    if matched_groups:
        return AuthorizationDecision(
            allowed=True,
            required_groups=normalized_required,
            matched_groups=matched_groups,
            reason=f"{access_label.capitalize()} access granted.",
        )

    return AuthorizationDecision(
        allowed=False,
        required_groups=normalized_required,
        matched_groups=(),
        reason=f"Session is missing a required {access_label} group.",
    )


def get_session_principal(
    request: Request,
    settings: AuthzSettings = Depends(get_authz_settings),
) -> SessionPrincipal:
    state_value = getattr(request.state, settings.state_principal_key, None)
    principal = principal_from_state(state_value, source="request_state")

    if principal is None:
        principal = principal_from_headers(
            request.headers,
            subject_headers=settings.subject_headers,
            email_headers=settings.email_headers,
            display_name_headers=settings.display_name_headers,
            group_headers=settings.group_headers,
            source="proxy_headers",
        )

    if principal is not None:
        return derive_roles(principal, settings)

    if settings.allow_anonymous or not settings.enabled:
        source = "anonymous" if settings.allow_anonymous else "disabled"
        return SessionPrincipal.anonymous(source=source)

    raise HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail="Authenticated session required.",
    )


def build_session_authorization_context(
    principal: SessionPrincipal,
    settings: AuthzSettings,
) -> SessionAuthorizationContext:
    return SessionAuthorizationContext(
        authentication_enabled=settings.enabled,
        allow_anonymous=settings.allow_anonymous,
        principal=principal,
        admin_access=evaluate_group_access(
            principal,
            settings.admin_groups,
            access_label="admin",
        ),
        reviewer_access=evaluate_group_access(
            principal,
            settings.reviewer_groups,
            access_label="reviewer",
        ),
    )


def require_admin_principal(
    principal: SessionPrincipal = Depends(get_session_principal),
    settings: AuthzSettings = Depends(get_authz_settings),
) -> SessionPrincipal:
    decision = evaluate_group_access(principal, settings.admin_groups, access_label="admin")
    if not decision.allowed:
        log_access_denied("session_rbac.admin", principal=principal, decision=decision)
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail=decision.reason,
        )
    return principal


